/** A jump the hand didn't make catches up on this: quick, no bounce. */
export declare const CATCH_UP: {
    readonly duration: 0.15;
    readonly bounce: 0;
};
/** Where the playhead is drawn (`x`) and where it's going (`target`), in seconds. */
export interface HeadPosition {
    readonly x: number;
    readonly target: number;
}
/**
 * The playhead's next move. A `jump` (a chapter or marker click, a loop's wrap, a press on the
 * lane away from it, play from elsewhere, a glide from code) catches up from where it's drawn when
 * it's more than `minGap` seconds away. A `follow` (a drag, the clock, a step) lands 1:1; during a
 * catch-up it shifts both ends, so it follows the hand and the remaining offset settles on its own.
 */
export declare function moveHead(head: HeadPosition, t: number, motion: "jump" | "follow", catching: boolean, minGap?: number): HeadPosition & {
    readonly catching: boolean;
};
/** The last marker at or before `t` (half a frame's leeway): the current chapter. */
export declare function currentMarker<M extends {
    readonly time: number;
}>(markers: readonly M[], t: number, fps: number): M | null;
/** A time as a player shows it: `m:ss` (`1:05`), `h:mm:ss` past an hour. */
export declare function minutes(t: number): string;
/** A line's segment bounds: 0, each chapter start inside the length (once each), the end. */
export declare function chapterBounds(times: readonly number[], duration: number): number[];
